/**
 * Response to a QueryOptionalExist, reporting whether an optional table exists
 */
public class ResponseOptionalExist : QueryResponseRecord {

	public bool tableExists;		// true if the queried table exists
	public bool wasCreated;		// true if this query caused creation of table

